edit(a,0,steps=['Identify purchase and attributable inbound/conversion costs that bring inventory to its present location and condition; not every incremental cost qualifies.','Include supplier purchase price less applicable discounts, inbound freight and non-recoverable duties under the accounting policy.','Allocate shared inbound costs across SKUs using a documented driver such as weight, volume or value.','Carry qualifying costs in inventory until the goods are sold, then recognize the related COGS.','Recalculate landed unit cost when supplier prices, exchange rates or freight change.'])
edit(a,1,steps=['Document the applicable accounting policy for inventory, cost of sales, fulfillment and selling expenses; timing before or after sale alone is not the classification test.','Track purchase cost, attributable inbound freight and duties as eligible inventory cost, expensed when sold.','Track outbound shipping, transaction fees, ads and storage separately so internal contribution can be reconciled to accounting gross profit.','Treat sale-price discounts in net revenue as applicable; do not automatically classify coupons as operating expenses.','Apply consistent definitions across Shopify, Amazon and reporting periods.'])
edit(a,3,title='Separate dropship product and shipping costs in margin analysis',summary='Compare dropship and stocked orders on complete order contribution, with a documented accounting policy.',steps=['Separate supplier product charges, inbound costs where relevant and customer-delivery charges.','Document how bundled supplier invoices are allocated and reported under the applicable policy.','Do not let free versus separately charged shipping alone determine accounting classification.','Include all merchant-paid delivery costs when comparing order contribution for stocked and dropship products.','Reconcile internal contribution reporting with the accountant\'s inventory and expense classifications.'])
r=read(DEST/'results'/f'{a}.json')['cards'][4];s=r['steps'];s[0]='Track return shipping separately using the documented accounting policy.';s[1]='Assess returned inventory condition, recoverable value and refurbishment costs; do not automatically capitalize all return labor or post it immediately to COGS.';edit(a,4,steps=s)
edit(a,7,steps=['Match supplier discounts and rebates to the affected goods and original purchase orders.','Reduce eligible inventory purchase cost for unsold affected goods and related cost of sales for sold goods as required by the accounting policy.','Record supplier returns with the corresponding stock movement and credit note.','Do not automatically post product-cost rebates as unrelated income.','Reconcile accruals and subsequent credits consistently; recognition is not a discretionary choice between past and future periods.'])
