for i,title in [(1,'Separate inbound inventory freight from customer delivery costs'),(4,'Classify ecommerce customer support costs consistently'),(5,'Separate partner commissions from product acquisition cost')]:
 edit(a,i,title=title,summary='Document the cost\'s economic purpose and accounting policy, then include variable selling and delivery costs in ecommerce contribution analysis.',steps=['Identify what the charge purchases: inventory, customer delivery, support, referral or another service.','Use the applicable accounting policy for statutory classification rather than a universal label from another business model.','Track the charge separately per order or channel where possible.','Reconcile gross profit to contribution after variable fulfillment, commissions and support costs before setting CAC limits.'],caveats=['Service and software examples in the source do not establish universal COGS rules for a physical-product store.'])
