for j,indices in [('792c8c8565ff1805732688e0',[1,9,11,14,15]),('6f67c11f404072a2db50669c',[12])]:
 p=DEST/'results'/f'{j}.json';r=read(p);b=DEST/'before-finance-review'/p.name
 if not b.exists():write(b,r)
